<template>
  <Dialog
    :visible="modelValue"
    @update:visible="$emit('update:modelValue', $event)"
    :modal="true"
    :draggable="false"
    header="替换词设置"
    :style="{ width: '90dvw', maxWidth: '540px' }"
    :content-style="{ maxHeight: '70dvh', overflow: 'auto' }"
  >
    <!-- 说明信息 -->
    <div
      class="my-1 shrink-0 rounded bg-(--quick-send-bg-sec) p-0.5"
    >
      <div class="kk-text-base opacity-80">
        <span class="icon-[mdi--information-outline]"></span>
        在这里可以设置需要替换成 user 名和 char 名的原始词汇列表。
      </div>
    </div>

    <!-- 列表编辑区域 -->
    <div class="min-h-0 flex-1 overflow-y-auto">
        <!-- 可复用的替换词列表模板定义 -->
        <DefineReplaceList
          v-slot="{
            title,
            emptyText,
            list,
            placeholder,
            add,
            remove,
            itemKeyPrefix,
            addTitle,
          }"
        >
          <div class="space-y-0.5">
            <div class="kk-text-base mb-0.5 font-semibold">
              {{ title }}
            </div>
            <div
              v-if="list.length === 0"
              class="kk-text-base text-(--quick-send-text)/70"
            >
              {{ emptyText }}
            </div>
            <div
              v-for="(_item, idx) in list"
              :key="itemKeyPrefix + idx"
              class="flex items-center gap-0.5"
            >
              <InputText
                size="small"
                v-model="list[idx]"
                class="flex-1 bg-(--quick-send-bg-sec)! text-(--quick-send-text)!"
                :placeholder="placeholder"
              />
              <Button
                size="small"
                severity="danger"
                text
                label="删除"
                @click="remove(idx)"
              />
            </div>
            <div class="mt-0.5">
              <Button
                size="small"
                text
                class="w-full border! border-dashed! border-(--quick-send-text)!"
                @click="add"
              >
                <span class="icon-[material-symbols--add-circle]"></span>
              </Button>
            </div>
          </div>
        </DefineReplaceList>

        <!-- user 部分 -->
        <UseReplaceList
          v-if="(props.type ?? activeTab) === 'user'"
          title="user 替换词列表"
          empty-text="目前没有任何 user 替换词，点击下面的加号可以添加。"
          :list="userList"
          placeholder="输入需要被替换的原始词汇"
          :add="addUser"
          :remove="removeUser"
          item-key-prefix="user-"
          add-title="添加 user 替换词"
        />

        <!-- char 部分 -->
        <UseReplaceList
          v-if="(props.type ?? activeTab) === 'char'"
          title="char 替换词列表"
          empty-text="目前没有任何 char 替换词，点击下面的加号可以添加。"
          :list="charList"
          placeholder="输入需要被替换的原始词汇"
          :add="addChar"
          :remove="removeChar"
          item-key-prefix="char-"
          add-title="添加 char 替换词"
        />
    </div>

    <template #footer>
      <Button size="small" text label="取消" @click="handleCancel" />
      <Button size="small" label="保存" @click="handleSave" />
    </template>
  </Dialog>
</template>

<script lang="ts" setup>
import { createReusableTemplate } from '@vueuse/core';
import { ref, watch } from 'vue';
import Dialog from 'primevue/dialog';
import Button from 'primevue/button';
import InputText from 'primevue/inputtext';

/**
 * 替换词数据结构
 */
export interface ReplaceNamesData {
  user: string[];
  char: string[];
}

const props = defineProps<{
  modelValue: boolean;
  data: ReplaceNamesData | null;
  /**
   * 弹窗类型：限定只编辑 user 或 char
   * 不传时可以在弹窗内自由切换
   */
  type?: 'user' | 'char';
}>();

const emit = defineEmits<{
  'update:modelValue': [value: boolean];
  save: [value: ReplaceNamesData];
}>();

/**
 * 当前激活的 Tab（user / char）
 */
const activeTab = ref<'user' | 'char'>('user');

/**
 * 本地可编辑列表
 */
const userList = ref<string[]>([]);
const charList = ref<string[]>([]);

/**
 * 使用 vueuse 的 createReusableTemplate 抽取可复用的列表模板
 */
const [DefineReplaceList, UseReplaceList] = createReusableTemplate<{
  title: string;
  emptyText: string;
  list: string[];
  placeholder: string;
  add: () => void;
  remove: (idx: number) => void;
  itemKeyPrefix: string;
  addTitle: string;
}>();

// 同步外部数据到本地列表
watch(
  () => props.data,
  d => {
    if (!d) return;
    userList.value = Array.isArray(d.user) ? [...d.user] : [];
    charList.value = Array.isArray(d.char) ? [...d.char] : [];
  },
  { immediate: true },
);

// 当弹窗打开时，默认切换到 user Tab
watch(
  () => props.modelValue,
  isOpen => {
    if (isOpen) {
      activeTab.value = props.type ?? 'user';
    }
  },
);

function addUser() {
  userList.value.push('');
}

function removeUser(idx: number) {
  userList.value.splice(idx, 1);
}

function addChar() {
  charList.value.push('');
}

function removeChar(idx: number) {
  charList.value.splice(idx, 1);
}

function handleSave() {
  const payload: ReplaceNamesData = {
    user: userList.value.map(v => v.trim()).filter(Boolean),
    char: charList.value.map(v => v.trim()).filter(Boolean),
  };
  emit('save', payload);
  emit('update:modelValue', false);
}

function handleCancel() {
  emit('update:modelValue', false);
}
</script>
