/**
 * 从父页面获取 CSS 变量值
 * @param variableName CSS 变量名（如 '--SmartThemeBlurTintColor'）
 * @returns CSS 变量值，如果获取失败则返回 undefined
 */
export function getParentThemeVariable(variableName: string): string | undefined {
  try {
    const parentRoot = window.parent.document.documentElement;
    const parentStyles = window.parent.getComputedStyle(parentRoot);
    const cssVarValue = parentStyles.getPropertyValue(variableName).trim();
    return cssVarValue || undefined;
  } catch (error) {
    console.warn('读取父页面主题变量失败', error);
    return undefined;
  }
}

/**
 * 移除颜色值中的 alpha 通道，支持多种颜色格式
 * @param color 颜色值（支持 rgba、rgb、hex 等格式）
 * @returns 移除 alpha 后的 rgb 颜色值
 */
export function removeColorAlpha(color: string | undefined): string | undefined {
  if (!color) return undefined;
  const trimmed = color.trim();

  // 旧式逗号分隔格式: rgba(r, g, b, a)
  const oldStyleMatch = trimmed.match(/^rgba\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*[\d.]+\s*\)$/i);
  if (oldStyleMatch) {
    return `rgb(${oldStyleMatch[1]}, ${oldStyleMatch[2]}, ${oldStyleMatch[3]})`;
  }

  // 新式空格分隔格式: rgb(r g b / a) 或 rgba(r g b / a)
  const newStyleMatch = trimmed.match(/^rgba?\(\s*(\d+)\s+(\d+)\s+(\d+)\s*\/\s*[\d.]+\s*\)$/i);
  if (newStyleMatch) {
    return `rgb(${newStyleMatch[1]}, ${newStyleMatch[2]}, ${newStyleMatch[3]})`;
  }

  // 十六进制带 alpha: #RRGGBBAA
  const hexAlphaMatch = trimmed.match(/^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})[0-9a-f]{2}$/i);
  if (hexAlphaMatch) {
    const r = parseInt(hexAlphaMatch[1], 16);
    const g = parseInt(hexAlphaMatch[2], 16);
    const b = parseInt(hexAlphaMatch[3], 16);
    return `rgb(${r}, ${g}, ${b})`;
  }

  return trimmed;
}

/**
 * 获取父页面的主题颜色配置
 * @returns 包含各类主题颜色的对象
 */
export function getThemeColors() {
  return {
    backgroundColor: removeColorAlpha(getParentThemeVariable('--SmartThemeBlurTintColor')),
    backgroundColorSecondary: removeColorAlpha(getParentThemeVariable('--SmartThemeChatTintColor')),
    textColor: removeColorAlpha(getParentThemeVariable('--SmartThemeBodyColor')),
    borderColor: removeColorAlpha(getParentThemeVariable('--SmartThemeBorderColor')),
    primaryColor: removeColorAlpha(getParentThemeVariable('--SmartThemeQuoteColor')),
    secondaryColor: removeColorAlpha(getParentThemeVariable('--SmartThemeUnderlineColor')),
  };
}

/**
 * 根据父页面的字体缩放比例设置 iframe 根元素的字体大小
 */
export function applyIframeRootRemFromParentMainFontSize(): void {
  const baseFontSize = 15;
  const ratio = ((window.parent as any).$('#font_scale_counter').val() as number) || 1;
  const fontSize = `${baseFontSize * ratio}px`;
  document.documentElement.style.fontSize = fontSize;
  document.documentElement.style.setProperty('--mainFontSize', fontSize);
}
