import { definePreset } from '@primeuix/themes';
import Aura from '@primeuix/themes/aura';

/** 主题颜色接口 */
export interface ThemeColors {
  backgroundColor?: string;
  backgroundColorSecondary?: string;
  textColor?: string;
  borderColor?: string;
  primaryColor?: string;
  secondaryColor?: string;
}

/** 降级兜底值（深色模式） */
const DEFAULT_BACKGROUND_COLOR = '#1a1a1a';
const DEFAULT_BACKGROUND_COLOR_SECONDARY = '#2a2a2a';
const DEFAULT_TEXT_COLOR = '#e0e0e0';
const DEFAULT_PRIMARY_COLOR = '#4a9eff';
const DEFAULT_SECONDARY_COLOR = '#6c757d';
const DEFAULT_BORDER_COLOR = '#3a3a3a';

/**
 * 创建基于酒馆主题的 PrimeVue 自定义预设
 * @param themeColors 主题颜色配置
 */
export function createCustomPreset(themeColors: ThemeColors) {
  const bgColor = themeColors.backgroundColor ?? DEFAULT_BACKGROUND_COLOR;
  const bgSecColor = themeColors.backgroundColorSecondary ?? DEFAULT_BACKGROUND_COLOR_SECONDARY;
  const txtColor = themeColors.textColor ?? DEFAULT_TEXT_COLOR;
  const borderColor = themeColors.borderColor ?? DEFAULT_BORDER_COLOR;
  const primaryColor = themeColors.primaryColor ?? DEFAULT_PRIMARY_COLOR;
  const secondaryColor = themeColors.secondaryColor ?? DEFAULT_SECONDARY_COLOR;

  return definePreset(Aura, {
    semantic: {
      colorScheme: {
        light: {
          primary: {
            color: primaryColor,
            activeColor: secondaryColor,
            hoverColor: primaryColor,
            contrastColor: bgColor,
          },
          highlight: {
            background: `color-mix(in srgb, ${primaryColor} 50%, transparent)`,
            focusBackground: '{highlight.background}',
            color: bgColor,
            focusColor: '{highlight.color}',
          },
          text: {
            color: txtColor,
            hoverColor: txtColor,
            mutedColor: `rgb(from ${txtColor} r g b / 0.5)`,
          },
          content: {
            background: bgColor,
            hoverBackground: bgSecColor,
            borderColor: borderColor,
            color: txtColor,
            hoverColor: txtColor,
          },
          formField: {
            color: txtColor,
            background: bgSecColor,
            filledBackground: bgSecColor,
            filledHoverBackground: bgSecColor,
            filledFocusBackground: bgSecColor,
            disabledBackground: 'color-mix(in srgb, black 50%, transparent)',
            borderColor: borderColor,
            hoverBorderColor: borderColor,
            paddingY: '0.5rem',
          },
          overlay: {
            select: {
              background: bgColor,
              borderColor: '{overlay.select.background}',
            },
            modal: {
              background: bgColor,
              borderColor: borderColor,
              padding: '1rem',
            },
            popover: {
              background: bgColor,
              borderColor: borderColor,
            },
          },
          list: {
            option: {
              focusBackground: 'rgba(0,0,0,0.1)',
            },
          },
        },
      },
    },
    components: {
      button: {
        root: {
          sm: {
            paddingY: '0.3rem',
            paddingX: '0.5rem',
          },
          iconOnlyWidth: '1.5rem',
        },
      },
      iftalabel: {
        colorScheme: {
          light: {
            root: {
              color: txtColor,
              focusColor: primaryColor,
              invalidColor: '{form.field.invalid.border.color}',
            },
          },
        },
      },
      togglebutton: {
        root: {
          sm: {
            padding: '0rem',
          },
        },
        colorScheme: {
          light: {
            root: {
              background: bgColor,
              checkedColor: bgColor,
              checkedBackground: primaryColor,
              checkedBorderColor: borderColor,
              borderColor: borderColor,
            },
            content: {
              checkedBackground: '{togglebutton.checked.background}',
            },
          },
        },
      },
      toggleswitch: {
        colorScheme: {
          light: {
            root: {
              checkedBackground: primaryColor,
            },
          },
        },
      },
      fileupload: {
        colorScheme: {
          light: {
            content: {
              padding: '0rem',
            },
          },
        },
      },
      picklist: {
        controls: {
          gap: '0.75rem',
        },
      },
      dialog: {
        title: {
          fontSize: '1.25rem',
        },
      },
    },
  } as Parameters<typeof definePreset>[1]);
}
