<template>
  <span ref="triggerRef" v-tooltip.top="'操作菜单'" class="icon-[iconamoon--menu-kebab-vertical-bold] cursor-pointer px-0.5" @click="toggle" />
  <Popover ref="op" :pt="popoverPT" :dt="popoverDT">
    <div class="flex gap-0.5">
      <span
        v-tooltip.top="'复制'"
        class="icon-[material-symbols--content-copy] h-1.25 w-1.25 cursor-pointer"
        @click="handle(onCopy)"
      />
      <span
        v-tooltip.top="'编辑'"
        class="icon-[material-symbols--edit-rounded] h-1.25 w-1.25 cursor-pointer"
        @click="handle(onEdit)"
      />
      <span
        v-tooltip.top="'删除'"
        class="icon-[material-symbols--delete] h-1.25 w-1.25 cursor-pointer"
        @click="handle(onDelete)"
      />
    </div>
  </Popover>
</template>

<script lang="ts" setup>
import Popover from 'primevue/popover';
import { ref } from 'vue';

defineProps<{
  onEdit?: () => void;
  onDelete?: () => void;
  onCopy?: () => void;
}>();

const op = ref<InstanceType<typeof Popover>>();
const triggerRef = ref<HTMLElement>();

/** Popover 设计令牌：反色配色（tooltip 风格） */
const popoverDT = {
  background: 'var(--quick-send-text)',
  color: 'var(--quick-send-bg)',
  border: { color: 'transparent' },
  shadow: 'none',
};

/** Popover PT：紧凑布局，通过 CSS 类控制居中 */
const popoverPT = {
  root: {
    class: 'action-menu-popover rounded-sm border-none',
  },
  content: {
    class: 'p-0.5',
  },
};

/**
 * 切换弹出层显隐，显式传递触发元素作为定位基准
 */
function toggle(e: Event) {
  op.value?.toggle(e, triggerRef.value);
}

/**
 * 执行操作并关闭弹出层
 */
function handle(fn?: () => void) {
  try {
    fn?.();
  } finally {
    op.value?.hide();
  }
}
</script>

<style>
/*
 * 操作菜单 Popover 居中修正
 * PrimeVue JS 按 arrow-offset 定位容器，这里用 translate 抵消偏移使容器居中，
 * 再将箭头伪元素强制到水平 50% 位置
 */
.action-menu-popover {
  translate: calc(-50% + var(--p-popover-arrow-offset, 1.25rem));
}

.action-menu-popover::before,
.action-menu-popover::after {
  left: 50% !important;
  translate: -50%;
}
</style>
