<script lang="ts" setup>
import {
  createReusableTemplate,
  useLocalStorage,
} from '@vueuse/core';
import _ from 'lodash';
import Breadcrumb from 'primevue/breadcrumb';
import Button from 'primevue/button';
import Dialog from 'primevue/dialog';
import {
  computed,
  inject,
  nextTick,
  onMounted,
  reactive,
  ref,
  toRaw,
  toRef,
  watch,
} from 'vue';
import { useDraggable } from 'vue-draggable-plus';
import ActionMenu from './ActionMenu.vue';
import EditKeyModal, { type EditSnapshot } from './EditKeyModal.vue';
import FixedPrefixSuffixModal, {
  type FixedPrefixSuffixData,
} from './FixedPrefixSuffixModal.vue';
import ReplaceNamesModal, {
  type ReplaceNamesData,
} from './ReplaceNamesModal.vue';
import { expandArrayLike, type DataPath } from './utils/data-parser';
import { getByPath } from './utils/deep-utils';
import {
  isSingleKeyObject as isSingleKeyObjectUtil,
  updateContainerWithPayload,
} from './utils/quicksend';
import { escapeForRegExp } from './utils/util';

const confirmDeleteId = ref<string | null>(null);
const isMobile = computed(() => SillyTavern?.isMobile());

/**
 * 可复用的前缀/后缀列表模板
 */
const [DefinePrefixSuffixList, ReusePrefixSuffixList] =
  createReusableTemplate<{
    list: any[];
    selectedIndexes: Set<number>;
    dragHandle: string;
    containerClass?: string;
    keyPrefix: string;
    onItemClick: (item: any, idx: number) => void;
    containerRef?: (el: any) => void;
    onAddClick?: () => void;
  }>();

/**
 * 是否处于编辑模式
 */
const editMode = ref(false);

/**
 * 编辑模态框是否打开
 */
const editOpen = ref(false);

/**
 * 替换词编辑弹窗是否打开
 */
const replaceNamesModalOpen = ref(false);

/**
 * 当前替换词弹窗编辑的类型（user / char）
 */
const replaceNamesType = ref<'user' | 'char'>('user');

/**
 * 编辑快照数据
 */
const editSnapshot = ref<EditSnapshot | null>(null);

/**
 * 当前编辑的节点ID
 */
const editNodeId = ref<string | null>(null);

/**
 * 原始数据
 */
const rawData = reactive(
  getVariables({ type: 'script', script_id: getScriptId() }),
);

if (!Array.isArray(rawData.data)) {
  rawData.data = [];
  replaceVariables(rawData, {
    type: 'script',
    script_id: getScriptId(),
  });
}

// if (typeof rawData.showTip !== 'boolean') {
//   rawData.showTip = true;
// }

if (
  rawData.popupSize == null ||
  typeof rawData.popupSize !== 'object'
) {
  rawData.popupSize = {
    desktop: { width: '50dvw', height: '60dvh' },
    mobile: { width: '90dvw', height: '80dvh' },
  };
  replaceVariables(rawData, {
    type: 'script',
    script_id: getScriptId(),
  });
}

const size = computed(() => ({
  mobileHeight: rawData.popupSize?.mobile?.height,
  mobileWidth: rawData.popupSize?.mobile?.width,
  desktopHeight: rawData.popupSize?.desktop?.height,
  desktopWidth: rawData.popupSize?.desktop?.width,
}));

if (
  rawData.replaceNames == null ||
  typeof rawData.replaceNames !== 'object' ||
  typeof rawData.replaceNames.user !== 'object' ||
  typeof rawData.replaceNames.char !== 'object'
) {
  rawData.replaceNames = { user: ['user'], char: ['character(s)'] };
  replaceVariables(rawData, {
    type: 'script',
    script_id: getScriptId(),
  });
}
// 确保 replaceNames 中的 user/char 为数组
if (!Array.isArray(rawData.replaceNames.user)) {
  rawData.replaceNames.user = Array.from(
    rawData.replaceNames.user ?? [],
  );
}
if (!Array.isArray(rawData.replaceNames.char)) {
  rawData.replaceNames.char = Array.from(
    rawData.replaceNames.char ?? [],
  );
}

/**
 * 数据：快速发送集
 * 使用 toRef 使其可直接修改，以便 useSortable 可以正常工作
 */
const quickSendData = toRef(rawData, 'data');

/**
 * 是否显示提示框
 */
// const showAlertTip = ref(rawData.showTip);

/**
 * 提示框的 DOM 引用
 */
// const alertTip = ref<HTMLElement | null>(null);

/**
 * 提示框的定时器
 */
// let alertTipTimer: ReturnType<typeof setTimeout> | null = null;

/**
 * 当前选中的第一级标签索引
 */
const activeTabIndex = ref(0);

/**
 * 当前选中的第二级标签索引
 */
const activeSecondIndex = ref(0);

interface LevelEntry {
  label: string;
  value: any;
  path: DataPath;
}

const level1Entries = computed<LevelEntry[]>(() => {
  const items = expandArrayLike(quickSendData.value, []);
  return items.map(item => ({
    label: item.label,
    value: item.value,
    path: item.path,
  }));
});

const level1Labels = computed<string[]>(() =>
  level1Entries.value.map(entry => entry.label),
);

/**
 * 验证拖拽索引是否有效
 * @param oldIndex 原始索引
 * @param newIndex 目标索引
 * @param listLength 列表长度
 * @returns 索引是否有效
 */
function isValidDragIndex(
  oldIndex: number | undefined,
  newIndex: number | undefined,
  listLength: number,
): boolean {
  if (oldIndex == null || newIndex == null) return false;
  if (oldIndex === newIndex) return false;
  if (oldIndex < 0 || oldIndex >= listLength) return false;
  if (newIndex < 0 || newIndex >= listLength) return false;
  return true;
}

/**
 * 拖拽列表的可写副本，供 useDraggable 使用
 * isDragging 为 true 时阻断外部数据同步，防止拖拽动画被打断
 */
const isDragging = ref(false);
const level1DragList = ref<LevelEntry[]>([]);
const level2DragList = ref<LevelEntry[]>([]);
const gridDragList = ref<string[]>([]);
const prefixDragList = ref<any[]>([]);
const suffixDragList = ref<any[]>([]);
watch(
  level1Entries,
  val => {
    if (!isDragging.value) level1DragList.value = [...val];
  },
  { immediate: true },
);

/** 拖拽容器 DOM 引用（供 useDraggable 使用） */
const level1ContainerRef = ref<HTMLElement | null>(null);
const level2ContainerRef = ref<HTMLElement | null>(null);
const gridContainerRef = ref<HTMLElement | null>(null);
const prefixContainer = ref<HTMLElement | null>(null);
const suffixContainer = ref<HTMLElement | null>(null);

const showPrefixList = ref(false);
const showSuffixList = ref(false);

const prefixList = computed<any[]>(
  () => (rawData.perfix || rawData.prefix || []) as any[],
);
const suffixList = computed<any[]>(
  () => (rawData.suffix || []) as any[],
);

const level2Entries = computed<LevelEntry[]>(() => {
  const level1Entry = level1Entries.value[activeTabIndex.value];
  if (!level1Entry) return [];
  const items = expandArrayLike(level1Entry.value, level1Entry.path);
  return items.map(item => ({
    label: item.label,
    value: item.value,
    path: item.path,
  }));
});

/**
 * 拖拽结束：二级标签页重排写回
 */
function handleLevel2DragEnd(event: {
  oldIndex?: number;
  newIndex?: number;
}) {
  isDragging.value = false;
  const { oldIndex, newIndex } = event;
  const level1Entry = level1Entries.value[activeTabIndex.value];
  if (!level1Entry || !Array.isArray(level1Entry.value)) return;
  const arr = [...level1Entry.value];
  if (!isValidDragIndex(oldIndex, newIndex, arr.length)) return;
  const [movedItem] = arr.splice(oldIndex!, 1);
  arr.splice(newIndex!, 0, movedItem);
  const path = level1Entry.path;
  if (path.length === 1) {
    rawData.data[path[0] as number] = arr;
  } else if (path.length === 2) {
    rawData.data[path[0] as number] = {
      [path[1] as string]: arr,
    } as any;
  }
  replaceVariables(_.cloneDeep(rawData), {
    type: 'script',
    script_id: getScriptId(),
  });
}

/**
 * 拖拽结束：一级标签页重排写回
 */
function handleLevel1DragEnd(event: {
  oldIndex?: number;
  newIndex?: number;
}) {
  isDragging.value = false;
  const { oldIndex, newIndex } = event;
  const arr = [...quickSendData.value];
  if (!isValidDragIndex(oldIndex, newIndex, arr.length)) return;
  const [movedItem] = arr.splice(oldIndex!, 1);
  arr.splice(newIndex!, 0, movedItem);
  rawData.data = arr as any;
  replaceVariables(_.cloneDeep(rawData), {
    type: 'script',
    script_id: getScriptId(),
  });
}

/**
 * 拖拽结束：网格视图重排写回（支持数组和对象两种结构）
 */
function handleGridDragEnd(event: {
  oldIndex?: number;
  newIndex?: number;
}) {
  isDragging.value = false;
  const { oldIndex, newIndex } = event;
  const baseEntry = gridBaseEntry.value;
  if (!baseEntry) return;
  let cur: any = toRaw(baseEntry.value ?? null);
  let currentPath: DataPath = [...baseEntry.path];
  for (let i = 0; i < gridPath.value.length; i++) {
    const idx = gridPath.value[i];
    const step = computeGridEntries(cur, currentPath);
    if (step.metas[idx]) currentPath = step.metas[idx].path;
    cur = toRaw(step.values[idx]);
  }
  const targetObj = getByPath(rawData.data, currentPath);
  if (Array.isArray(targetObj)) {
    const arr = targetObj.map(it => toRaw(it));
    if (!isValidDragIndex(oldIndex, newIndex, arr.length)) return;
    const [movedItem] = arr.splice(oldIndex!, 1);
    arr.splice(newIndex!, 0, movedItem);
    if (currentPath.length === 0) {
      rawData.data = arr as any;
    } else {
      const parentPath = currentPath.slice(0, -1);
      const targetKey = currentPath[currentPath.length - 1];
      if (parentPath.length === 0) {
        if (typeof targetKey === 'number')
          rawData.data[targetKey] = arr as any;
      } else {
        const parent = getByPath(rawData.data, parentPath);
        if (Array.isArray(parent) && typeof targetKey === 'number') {
          parent[targetKey] = arr as any;
        } else if (
          typeof parent === 'object' &&
          parent !== null &&
          typeof targetKey === 'string'
        ) {
          (parent as any)[targetKey] = arr;
        }
      }
    }
  } else if (typeof targetObj === 'object' && targetObj !== null) {
    const rawObj = toRaw(targetObj as Record<string, any>);
    const keys = Object.keys(rawObj);
    if (!isValidDragIndex(oldIndex, newIndex, keys.length)) return;
    const [movedKey] = keys.splice(oldIndex!, 1);
    keys.splice(newIndex!, 0, movedKey);
    const newObj: any = {};
    for (const k of keys) newObj[k] = toRaw(rawObj[k]);
    if (currentPath.length === 0) {
      rawData.data = newObj as any;
    } else {
      const parentPath = currentPath.slice(0, -1);
      const targetKey = currentPath[currentPath.length - 1];
      if (parentPath.length === 0) {
        (rawData.data as any)[targetKey] = newObj;
      } else {
        const parent = getByPath(rawData.data, parentPath);
        if (Array.isArray(parent) && typeof targetKey === 'number') {
          parent[targetKey] = newObj as any;
        } else if (
          typeof parent === 'object' &&
          parent !== null &&
          typeof targetKey === 'string'
        ) {
          (parent as any)[targetKey] = newObj;
        }
      }
    }
  }
  replaceVariables(_.cloneDeep(toRaw(rawData)), {
    type: 'script',
    script_id: getScriptId(),
  });
}

/**
 * 拖拽结束：前缀列表重排写回
 */
function handlePrefixDragEnd(event: {
  oldIndex?: number;
  newIndex?: number;
}) {
  isDragging.value = false;
  const { oldIndex, newIndex } = event;
  const list = [...prefixList.value];
  if (!isValidDragIndex(oldIndex, newIndex, list.length)) return;
  const [movedItem] = list.splice(oldIndex!, 1);
  list.splice(newIndex!, 0, movedItem);
  if (rawData.perfix) rawData.perfix = list as any;
  else rawData.prefix = list as any;
  replaceVariables(_.cloneDeep(rawData), {
    type: 'script',
    script_id: getScriptId(),
  });
}

/**
 * 拖拽结束：后缀列表重排写回
 */
function handleSuffixDragEnd(event: {
  oldIndex?: number;
  newIndex?: number;
}) {
  isDragging.value = false;
  const { oldIndex, newIndex } = event;
  const list = [...suffixList.value];
  if (!isValidDragIndex(oldIndex, newIndex, list.length)) return;
  const [movedItem] = list.splice(oldIndex!, 1);
  list.splice(newIndex!, 0, movedItem);
  rawData.suffix = list as any;
  replaceVariables(_.cloneDeep(rawData), {
    type: 'script',
    script_id: getScriptId(),
  });
}

