/**
 * 网格导航路径
 *
 * 记录从第三级开始的导航路径，用于实现多层级下钻导航
 */
const gridPath = ref<number[]>([]);

const gridBaseEntry = computed<LevelEntry | null>(
  () => level2Entries.value[activeSecondIndex.value] ?? null,
);

type GridEntryMeta = { path: DataPath };

function computeGridEntries(
  node: any,
  basePath: DataPath,
): { labels: string[]; values: any[]; metas: GridEntryMeta[] } {
  const items = expandArrayLike(node, basePath);
  return {
    labels: items.map(item => item.label),
    values: items.map(item => item.value),
    metas: items.map(item => ({ path: item.path })),
  };
}

const gridCurrent = computed(() => {
  const baseEntry = gridBaseEntry.value;
  if (!baseEntry) return { labels: [], values: [], metas: [] };
  let cur: any = baseEntry.value;
  let curPath: DataPath = baseEntry.path;
  for (const idx of gridPath.value) {
    const step = computeGridEntries(cur, curPath);
    const meta = step.metas[idx];
    if (!meta) return { labels: [], values: [], metas: [] };
    cur = step.values[idx];
    curPath = meta.path;
  }
  return computeGridEntries(cur, curPath);
});

const gridLabels = computed(() => gridCurrent.value.labels);
const gridValues = computed(() => gridCurrent.value.values);
