/**
 * 本地记忆部分：最后一次选中的层级索引
 *
 * 结构：{ l1: 第一级索引, l2: 第二级索引, path: 下钻路径, sel: 当前层选中索引 }
 */
type LastSelection = {
  l1: number;
  l2: number;
  path: number[];
  sel: number | null;
};
const lastSelection = useLocalStorage<LastSelection>(
  'quicksend:lastSelection',
  {
    l1: 0,
    l2: 0,
    path: [],
    sel: null,
  },
);

// 变更即写入本地存储（先记录层级与路径，选中项单独监听在其定义之后）
watch(
  [activeTabIndex, activeSecondIndex, gridPath],
  ([l1, l2, path]) => {
    lastSelection.value = {
      l1,
      l2,
      path: Array.isArray(path) ? [...path] : [],
      sel: lastSelection.value?.sel ?? null,
    };
  },
);

/**
 * 启动时尝试恢复；如果无效则按“能到的最后层级的第一号”回退
 */
onMounted(() => {
  const saved = lastSelection.value;
  if (!saved) return;

  // 校验并设置第一级
  const l1Max = level1Entries.value.length;
  const validL1 =
    l1Max > 0 && saved.l1 >= 0 && saved.l1 < l1Max ? saved.l1 : 0;
  activeTabIndex.value = validL1;

  // 校验并设置第二级（依赖于已设置好的 l1）
  const l2Max = level2Entries.value.length;
  const validL2 =
    l2Max > 0 && saved.l2 >= 0 && saved.l2 < l2Max ? saved.l2 : 0;
  activeSecondIndex.value = validL2;

  // 逐步验证下钻路径，保留能到达的最长前缀
  const base = gridBaseEntry.value;
  if (!base) {
    gridPath.value = [];
    selectedGridIndex.value = null;
    return;
  }
  let cur: any = base.value;
  let curPath = base.path;
  const prefix: number[] = [];
  for (const stepIdx of saved.path ?? []) {
    const step = computeGridEntries(cur, curPath);
    if (stepIdx < 0 || stepIdx >= step.labels.length) break;
    prefix.push(stepIdx);
    cur = step.values[stepIdx];
    curPath = step.metas[stepIdx]?.path ?? curPath;
  }
  gridPath.value = prefix;
  // 恢复该层的选中项；无效则回退到第一项
  const current = computeGridEntries(cur, curPath);
  const savedSel = saved.sel;
  if (
    typeof savedSel === 'number' &&
    savedSel >= 0 &&
    savedSel < current.labels.length
  ) {
    // 若有有效的历史选中项，则选中并模拟一次点击，触发文本处理显示
    selectedGridIndex.value = savedSel;
    nextTick(() => onGridEntryClick(savedSel));
  } else if (current.labels.length > 0) {
    // 无有效历史选中项但当前层有数据，则默认选中第一个并触发一次点击
    selectedGridIndex.value = 0;
    nextTick(() => onGridEntryClick(0));
  } else {
    selectedGridIndex.value = null;
  }
});

