/**
 * 应用宏替换到文本
 *
 * @param text - 要处理的文本
 * @returns 处理后的文本
 */
function applyMacroToText(text: string): string {
  let processed = text;
  // 根据 rawData.replaceNames 中配置的关键词列表进行宏替换
  if (
    replaceUserNames.value &&
    userName &&
    rawData.replaceNames?.user
  ) {
    const userSet = new Set<string>(
      rawData.replaceNames.user as string[],
    );
    userSet.forEach(raw => {
      if (!raw) return;
      const pattern = escapeForRegExp(raw);
      const reg = new RegExp(pattern, 'gi');
      processed = processed.replace(reg, userName);
    });
  }
  if (
    replaceCharNames.value &&
    charName &&
    rawData.replaceNames?.char
  ) {
    const charSet = new Set<string>(
      rawData.replaceNames.char as string[],
    );
    charSet.forEach(raw => {
      if (!raw) return;
      const pattern = escapeForRegExp(raw);
      const reg = new RegExp(pattern, 'gi');
      processed = processed.replace(reg, charName);
    });
  }
  return processed;
}

/**
 * 替换用户名和角色名为宏，并进行宏替换
 *
 * 对原始文本、前缀、后缀、固定前后缀都应用宏替换（不包含酒馆文本）
 * 酒馆文本会单独追加到末尾，不受宏替换影响
 */
function applyMacroSubstitution() {
  // 对原始文本应用宏替换
  const processedText = applyMacroToText(originalText.value);

  // 根据当前已选前缀/后缀与固定前后缀，自动拼接展示文本（让文本框中也可见固定前后缀）
  const buildSelectedConcat = (
    list: any[],
    selected: Set<number>,
  ) => {
    let out = '';
    list.forEach((item, idx) => {
      if (selected.has(idx)) {
        const v = getPrefixSuffixValue(item);
        if (v) out += v;
      }
    });
    return out;
  };

  const prefixConcatRaw = buildSelectedConcat(
    prefixList.value,
    selectedPrefixIndexes.value,
  );
  const suffixConcatRaw = buildSelectedConcat(
    suffixList.value,
    selectedSuffixIndexes.value,
  );
  const fixedPreRaw = fixedPrefix.value || '';
  const fixedSufRaw = fixedSuffix.value || '';

  // 对前后缀和固定前后缀也应用宏替换
  const fixedPre = applyMacroToText(fixedPreRaw);
  const prefixConcat = applyMacroToText(prefixConcatRaw);
  const suffixConcat = applyMacroToText(suffixConcatRaw);
  const fixedSuf = applyMacroToText(fixedSufRaw);

  // 拼接处理后的文本（固定前后缀需要出现在最外层，保持与发送时一致的可视效果）
  const mainText = `${fixedPre}${prefixConcat}${processedText}${suffixConcat}${fixedSuf}`;

  // 最后追加酒馆文本（不应用宏替换）
  text.value = tavernText.value
    ? `${mainText}\n\n${tavernText.value}`
    : mainText;
}

