 *
 * @param node - 要检查的节点
 * @returns 如果是字符串则返回该字符串，否则返回 undefined
 */
function nodeContent(node: any): string | undefined {
  return typeof node === 'string' ? node : undefined;
}

/**
 * 选择第一级标签
 *
 * 当用户点击第一级标签时触发，在非编辑模式下切换到对应的标签
 * 切换到指定的第一级标签，并重置第二级标签和网格路径，同时清除当前选中的网格项
 *
 * @param idx - 要选择的第一级标签索引
 */
function selectLevel1(idx: number) {
  if (editMode.value) {
    return;
  }
  if (idx === activeTabIndex.value) return;
  activeTabIndex.value = idx;
  activeSecondIndex.value = 0;
  gridPath.value = [];
  selectedGridIndex.value = null;
}

/**
 * 选择第二级标签
 *
 * 当用户点击第二级标签时触发，在非编辑模式下切换到对应的标签
 * 切换到指定的第二级标签，并重置网格路径
 *
 * @param idx - 要选择的第二级标签索引
 */
function selectLevel2(idx: number) {
  if (editMode.value) {
    return;
  }
  if (idx === activeSecondIndex.value) return;
  activeSecondIndex.value = idx;
  gridPath.value = [];
  selectedGridIndex.value = null;
}

/**
 * 处理网格条目点击
 *
 * 当用户点击网格中的条目时触发，在非编辑模式下处理点击逻辑
 * 如果条目是字符串则显示在文本框中，如果条目是对象或数组，则进入下一层导航
 *
 * @param idx - 被点击的网格条目索引
 */
function onGridEntryClick(idx: number) {
  if (editMode.value) {
    return;
  }
  selectedGridIndex.value = idx;
  const entry = gridValues.value[idx];
  const c = nodeContent(entry);
  if (c != null) {
    originalText.value = c;
    appendSillyTavernText();
    return;
  }
  gridPath.value = [...gridPath.value, idx];
  selectedGridIndex.value = 0;
}

/**
 * 面包屑导航路径
 *
 * 根据当前选中的第一级、第二级标签和网格路径生成面包屑导航
 * 用于显示当前在数据层级中的位置
 */
const breadcrumbs = computed(() => {
  const out: string[] = [];
  const l1 = level1Labels.value[activeTabIndex.value];
  if (l1) out.push(l1);
  const l2 = level2Labels.value[activeSecondIndex.value];
  if (l2 != null) out.push(l2);
  const baseEntry = gridBaseEntry.value;
  if (!baseEntry) return out;
  let cur: any = baseEntry.value;
  let curPath: DataPath = baseEntry.path;
  for (const idx of gridPath.value) {
    const step = computeGridEntries(cur, curPath);
    if (idx >= 0 && idx < step.labels.length)
      out.push(step.labels[idx]);
    const meta = step.metas[idx];
    if (!meta) break;
    cur = step.values[idx];
    curPath = meta.path;
  }
  return out;
});

/**
 * 面包屑 PrimeVue MenuItem 模型
 *
 * 将字符串路径转为 MenuItem[]，非末项带 command 可点击导航
 */
const breadcrumbModel = computed(() =>
  breadcrumbs.value.map((label, idx) => ({
    label,
    ...(idx < breadcrumbs.value.length - 1
      ? { command: () => navigateTo(idx) }
      : {}),
  })),
);

/**
 * 导航到指定层级
 *
 * 根据面包屑索引导航到对应的层级，用于实现面包屑导航功能
 * 在编辑模式下不执行导航操作
 *
 * @param idx - 面包屑索引，0和1对应第一级和第二级，2及以上对应网格层级
 */
function navigateTo(idx: number) {
  if (editMode.value) return;
  selectedGridIndex.value = null;
  if (idx < 0) {
    gridPath.value = [];
    return;
  }
  if (idx <= 1) {
    gridPath.value = [];
    return;
  }
  gridPath.value = gridPath.value.slice(0, idx - 2);
}

/**
 * 监听第一级标签变化
 *
 * 当第一级标签数组长度变化时，确保当前选中的索引不超出范围
 */
watch(level1Labels, list => {
  if (activeTabIndex.value >= list.length) activeTabIndex.value = 0;
});

/**
 * 监听第二级标签变化
 *
 * 当第二级标签数组长度变化时，确保当前选中的索引不超出范围
 */
watch(level2Labels, list => {
  if (activeSecondIndex.value >= list.length)
    activeSecondIndex.value = 0;
});

/**
 * 创建子节点的编辑快照
 *
 * 为编辑模态框创建子节点的快照数据，包含节点的基本信息
 * 支持对象和数组两种类型的节点处理
 *
 * @param node - 要创建快照的节点
 * @returns 子节点快照数组
 */
function makeChildrenSnapshot(node: any): EditSnapshot['children'] {
  const items: EditSnapshot['children'] = [];
  if (node == null) return items;

  if (typeof node === 'object' && !Array.isArray(node)) {
    for (const k of Object.keys(node)) {
      const v = (node as any)[k];
      items.push({
        id: `key:${k}`,
        name: k,
        canRename: true,
        isLeaf: typeof v === 'string',
        value: typeof v === 'string' ? v : undefined,
      });
    }
  } else if (Array.isArray(node)) {
    node.forEach((el, i) => {
      if (typeof el === 'string') {
        items.push({
          id: `arridx:${i}`,
          name: `#${i}`,
          canRename: false,
          isLeaf: true,
          value: el,
        });
      } else if (
        el &&
        typeof el === 'object' &&
        !Array.isArray(el) &&
        isSingleKeyObjectUtil(el)
      ) {
        const k = Object.keys(el)[0];
        const v = (el as any)[k];
        items.push({
          id: `arridx:${i}`,
          name: k,
          canRename: true,
          isLeaf: typeof v === 'string',
          value: typeof v === 'string' ? v : undefined,
        });
      } else {
        items.push({
          id: `arridx:${i}`,
          name: `#${i}`,
          canRename: false,
          isLeaf: false,
        });
      }
    });
  }
  return items;
}

/**
 * 路径段类型定义
 *
 * 用于描述数据路径中的每个段，包含类型和键名
 */
function makeIdFromPath(path: DataPath): string {
  return JSON.stringify(path);
}

function parseId(id: string): DataPath {
  if (!id || id.startsWith('prefix:') || id.startsWith('suffix:'))
    return [];
  try {
    const parsed = JSON.parse(id);
    return Array.isArray(parsed) ? (parsed as DataPath) : [];
  } catch (error) {
    return [];
  }
}

function resolveById(
  root: any,
  id: string,
): {
  container: any;
  keyInContainer: string | number;
  title: string;
  value: any;
  canRename: boolean;
  isLeaf: boolean;
  path: DataPath;
} | null {
  const path = parseId(id);
  if (path.length === 0) return null;

  const containerPath = path.slice(0, -1);
  const lastKey = path[path.length - 1];
  const container =
    containerPath.length === 0
      ? root
      : getByPath(root, containerPath);
  if (container == null) return null;

  if (Array.isArray(container) && typeof lastKey === 'number') {
    const element = container[lastKey];

    if (typeof element === 'string') {
      return {
        container,
        keyInContainer: lastKey,
        title: `#${lastKey}`,
        value: element,
        canRename: false,
        isLeaf: true,
        path,
      };
    }
    if (
      element &&
      typeof element === 'object' &&
      !Array.isArray(element) &&
      isSingleKeyObjectUtil(element)
    ) {
      const innerKey = Object.keys(element)[0];
      const innerValue = (element as any)[innerKey];
      return {
        container: element,
        keyInContainer: innerKey,
        title: innerKey,
        value: innerValue,
        canRename: true,
        isLeaf: typeof innerValue === 'string',
        path,
      };
    }
    return {
      container,
      keyInContainer: lastKey,
      title: `#${lastKey}`,
      value: element,
      canRename: false,
      isLeaf: typeof element === 'string',
      path,
    };
  }

  const value = getByPath(root, path);
  const title =
    typeof lastKey === 'string'
      ? lastKey
      : typeof lastKey === 'number'
        ? `#${lastKey}`
        : String(lastKey);
  const canRename = typeof lastKey === 'string';

  return {
    container,
    keyInContainer: lastKey as string | number,
    title,
    value,
    canRename,
    isLeaf: typeof value === 'string',
    path,
  };
}
function makeIdForLevel1Idx(idx: number): string {
  const entry = level1Entries.value[idx];
  const path = entry?.path ?? ([idx] as DataPath);
  return makeIdFromPath(path);
}

function makeIdForLevel2Idx(idx: number): string {
  const entry = level2Entries.value[idx];
  if (!entry) return makeIdForLevel1Idx(activeTabIndex.value);
  return makeIdFromPath(entry.path);
}

function makeIdForGridIdx(idx: number): string {
  const baseEntry = level2Entries.value[activeSecondIndex.value];
  if (!baseEntry) return makeIdForLevel1Idx(activeTabIndex.value);
  let current: any = baseEntry.value;
  let currentPath: DataPath = baseEntry.path;
  for (const stepIdx of gridPath.value) {
    const step = computeGridEntries(current, currentPath);
    const meta = step.metas[stepIdx];
    if (!meta) return makeIdFromPath(currentPath);
    current = step.values[stepIdx];
    currentPath = meta.path;
  }
  const step = computeGridEntries(current, currentPath);
  const targetMeta = step.metas[idx];
  return makeIdFromPath(targetMeta ? targetMeta.path : currentPath);
}
function openEdit(idx: number, scope: 'l1' | 'l2' | 'grid') {
  const id =
    scope === 'grid'
      ? makeIdForGridIdx(idx)
      : scope === 'l2'
        ? makeIdForLevel2Idx(idx)
        : makeIdForLevel1Idx(idx);
  const resolved = resolveById(quickSendData.value, id);
  if (!resolved) return;

  editNodeId.value = id;
  editSnapshot.value = {
    title: resolved.title,
    name: resolved.title,
    canRename: resolved.canRename,
    isLeaf: resolved.isLeaf,
    value: resolved.isLeaf ? (resolved.value as string) : undefined,
    children: makeChildrenSnapshot(resolved.value),
  };
  editOpen.value = true;
}

/**
 * 打开创建新项的模态框
 *
 * @param scope - 创建项所在的层级
 */
function openCreate(scope: 'l1' | 'l2' | 'grid') {
  editNodeId.value = `__create__:${scope}`;
  editSnapshot.value = {
    title: '新建项',
    name: '',
    canRename: true,
    isLeaf: false,
    value: undefined,
    children: [],
    isCreate: true,
    createLevel: scope,
  };
  editOpen.value = true;
}

/**
 * 处理编辑保存
 *
 * 将编辑模态框中的修改应用到实际数据中
 * 支持修改节点名称、值和子节点，并处理不同类型的容器（数组和对象）
 *
 * @param payload - 编辑保存的数据，包含新名称、新值和子节点修改
 */
function handleEditSave(payload: {
  newName?: string;
  newValue?: string;
  children: Array<{
    id: string;
    newName?: string;
    newValue?: string;
  }>;
  __create?: boolean;
  __createAsLeaf?: boolean;
}) {
  const id = editNodeId.value;
  if (!id) return;

  if (id.startsWith('__create__:')) {
    const scope = id.slice(11);
    const newName = payload.newName || '新项';

    if (scope === 'prefix') {
      const newItem = { [newName]: payload.newValue ?? '' };
      if (!rawData.prefix && !rawData.perfix) {
        rawData.prefix = [];
      }
      const list = rawData.perfix || rawData.prefix;
      if (Array.isArray(list)) {
        list.push(newItem);
      }
    } else if (scope === 'suffix') {
      const newItem = { [newName]: payload.newValue ?? '' };
      if (!rawData.suffix) {
        rawData.suffix = [];
      }
      rawData.suffix.push(newItem);
    } else if (scope === 'l1') {
      const newItem = { [newName]: [] };
      quickSendData.value.push(newItem);
    } else if (scope === 'l2') {
      const level1Entry = level1Entries.value[activeTabIndex.value];
      if (level1Entry && Array.isArray(level1Entry.value)) {
        const newItem = { [newName]: [] };
        level1Entry.value.push(newItem);
      }
    } else if (scope === 'grid') {
      const baseEntry = gridBaseEntry.value;
      if (!baseEntry) return;

      let targetArray: any = baseEntry.value;
      for (const idx of gridPath.value) {
        const step = computeGridEntries(targetArray, baseEntry.path);
        targetArray = step.values[idx];
      }

      if (Array.isArray(targetArray)) {
        const newItem = payload.__createAsLeaf
          ? { [newName]: payload.newValue ?? '' }
          : { [newName]: [] };
        targetArray.push(newItem);
      } else if (
        typeof targetArray === 'object' &&
        targetArray !== null
      ) {
        if (payload.__createAsLeaf) {
          (targetArray as any)[newName] = payload.newValue ?? '';
        } else {
          (targetArray as any)[newName] = [];
        }
      }
    }

    persistEditResult();
    return;
  }

  if (id.startsWith('prefix:')) {
    const idx = Number(id.slice(7));
    const list = prefixList.value;
    const item = list[idx];
    if (item && typeof item === 'object') {
      const oldKey = Object.keys(item)[0];
      if (payload.newName && payload.newName !== oldKey) {
        delete (item as any)[oldKey];
        (item as any)[payload.newName] = payload.newValue ?? '';
      } else if (payload.newValue != null) {
        (item as any)[oldKey] = payload.newValue;
      }
    }
    persistEditResult();
    return;
  }

  if (id.startsWith('suffix:')) {
    const idx = Number(id.slice(7));
    const list = suffixList.value;
    const item = list[idx];
    if (item && typeof item === 'object') {
      const oldKey = Object.keys(item)[0];
      if (payload.newName && payload.newName !== oldKey) {
        delete (item as any)[oldKey];
        (item as any)[payload.newName] = payload.newValue ?? '';
      } else if (payload.newValue != null) {
        (item as any)[oldKey] = payload.newValue;
      }
    }
    persistEditResult();
    return;
  }

  const resolved = resolveById(quickSendData.value, id);
  if (!resolved) return;
  const { container, keyInContainer } = resolved;

  updateContainerWithPayload({
    container,
    keyInContainer,
    payload,
  });

  persistEditResult();
}

/**
 * 通用复制函数：复制指定项并在同级添加一份
 *
 * @param idx - 要复制的项索引
 * @param scope - 层级类型，'l1'、'l2' 或 'grid'
 */
function handleCopy(idx: number, scope: 'l1' | 'l2' | 'grid') {
  // 根据 scope 获取对应的 ID
  const id =
    scope === 'grid'
      ? makeIdForGridIdx(idx)
      : scope === 'l1'
        ? makeIdForLevel1Idx(idx)
        : makeIdForLevel2Idx(idx);
  if (!id) return;

  const resolved = resolveById(quickSendData.value, id);
  if (!resolved) return;

  const { container, keyInContainer, path, value } = resolved;
  const lastPathKey = _.last(path);
  const secondLastPathKey =
    path.length >= 2 ? path[path.length - 2] : undefined;

  // 判断 container 是否为单键对象
  const isSingleKeyObjectCase =
    _.isPlainObject(container) &&
    isSingleKeyObjectUtil(container) &&
    _.isString(keyInContainer) &&
    (_.isNumber(secondLastPathKey) || _.isNumber(lastPathKey));

  // 处理对象的情况（单键对象或普通对象）
  if (
    isSingleKeyObjectCase ||
    (_.isPlainObject(container) && _.isString(keyInContainer))
  ) {
    let parentContainer: any = null;
    let arrayIndexInPath: number | null = null;
    let isInArray = false;

    // 尝试找到父数组（单键对象的情况）
    if (isSingleKeyObjectCase) {
      const arrayIndex = _.isNumber(lastPathKey)
        ? lastPathKey
        : _.isNumber(secondLastPathKey)
          ? secondLastPathKey
          : null;

      if (arrayIndex !== null) {
        const parentPath = _.isNumber(lastPathKey)
          ? _.initial(path)
          : path.length >= 2
            ? path.slice(0, -2)
            : [];

        const foundParent = _.isEmpty(parentPath)
          ? quickSendData.value
          : getByPath(quickSendData.value, parentPath);

        if (_.isArray(foundParent)) {
          parentContainer = foundParent;
          arrayIndexInPath = arrayIndex;
          isInArray = true;
        }
      }
    }

    // 获取当前键名和值
    const oldKey = keyInContainer as string;
    const copiedValue = _.cloneDeep(value);

    // 生成新的唯一键名
    let newKey = `${oldKey}_副本`;
    let counter = 1;

    if (isInArray && parentContainer) {
      // 检查数组中是否已有相同键名的单键对象
      while (
        parentContainer.some(
          (item: any) =>
            _.isPlainObject(item) &&
            isSingleKeyObjectUtil(item) &&
            Object.keys(item)[0] === newKey,
        )
      ) {
        newKey = `${oldKey}_副本${counter}`;
        counter++;
      }

      // 创建新的单键对象并插入到数组中
      const newSingleKeyObject = { [newKey]: copiedValue };
      const insertIndex = arrayIndexInPath! + 1;

      parentContainer.splice(insertIndex, 0, newSingleKeyObject);
    } else {
      // 普通对象，直接在 container 中生成新 key
      while (_.has(container, newKey)) {
        newKey = `${oldKey}_副本${counter}`;
        counter++;
      }

      // 深拷贝值并添加到对象中
      _.set(container, newKey, copiedValue);
    }
  }

  // 保存数据
  replaceVariables(_.cloneDeep(rawData), {
    type: 'script',
    script_id: getScriptId(),
  });
}

/**
 * 复制前缀或后缀项并在同级添加一份
 *
 * @param idx - 要复制的项索引
 * @param type - 类型，'prefix' 或 'suffix'
 */
function handleCopyPrefixSuffix(
  idx: number,
  type: 'prefix' | 'suffix',
) {
  const list =
    type === 'prefix' ? prefixList.value : suffixList.value;
  if (!Array.isArray(list) || idx < 0 || idx >= list.length) return;

  const item = list[idx];
  if (!item || typeof item !== 'object') return;

  // 获取当前键名和值
  const oldKey = getPrefixSuffixKey(item);
  const oldValue = getPrefixSuffixValue(item);

  // 生成新的唯一键名
  let newKey = `${oldKey}_副本`;
  let counter = 1;

  // 检查列表中是否已有相同键名的项
  while (
    list.some(
      (it: any) =>
        it &&
        typeof it === 'object' &&
        !Array.isArray(it) &&
        Object.keys(it)[0] === newKey,
    )
  ) {
    newKey = `${oldKey}_副本${counter}`;
    counter++;
  }

  // 深拷贝值并创建新的单键对象
  const copiedValue = _.cloneDeep(oldValue);
  const newItem = { [newKey]: copiedValue };

  // 在当前位置之后插入新项
  list.splice(idx + 1, 0, newItem);

  // 更新 rawData
  if (type === 'prefix') {
    if (rawData.perfix) {
      rawData.perfix = list as any;
    } else {
      rawData.prefix = list as any;
    }
  } else {
    rawData.suffix = list as any;
  }

  // 保存数据
  replaceVariables(_.cloneDeep(rawData), {
    type: 'script',
    script_id: getScriptId(),
  });
}

/**
 * 删除指定索引的条目及其子级
 *
 * @param idx - 要删除的网格项索引
 */
function handleDeleteById(id: string) {
  if (!id) return;

  // 删除前后缀
  if (id.startsWith('prefix:')) {
    const idx = Number(id.slice(7));
    const list = prefixList.value;
    if (Array.isArray(list) && idx >= 0 && idx < list.length) {
      list.splice(idx, 1);
      if (rawData.perfix) rawData.perfix = list as any;
      else rawData.prefix = list as any;
    }
  } else if (id.startsWith('suffix:')) {
    const idx = Number(id.slice(7));
    const list = suffixList.value;
    if (Array.isArray(list) && idx >= 0 && idx < list.length) {
      list.splice(idx, 1);
      rawData.suffix = list as any;
    }
  } else {
    // 通用路径删除（l1/l2/grid 任意层）
    const resolved = resolveById(quickSendData.value, id);
    if (!resolved) {
      confirmDeleteId.value = null;
      return;
    }
    const { container, keyInContainer, path } = resolved;

    if (Array.isArray(container)) {
      container.splice(keyInContainer as number, 1);
    } else if (typeof container === 'object' && container !== null) {
      delete (container as any)[keyInContainer];
      // 如果删除后对象为空且位于上层数组中，则移除该数组元素
      try {
        const containerPath = path.slice(0, -1);
        const parentPath = containerPath.slice(0, -1);
        const idxInParent = containerPath[containerPath.length - 1];
        const parentContainer =
          parentPath.length === 0
            ? quickSendData.value
            : getByPath(quickSendData.value, parentPath);
        if (
          parentContainer &&
          Array.isArray(parentContainer) &&
          typeof idxInParent === 'number' &&
          container &&
          typeof container === 'object' &&
          Object.keys(container).length === 0
        ) {
          parentContainer.splice(idxInParent, 1);
        }
      } catch (_e) {
        /* ignore */
      }
    }
  }

  replaceVariables(_.cloneDeep(rawData), {
    type: 'script',
    script_id: getScriptId(),
  });
  confirmDeleteId.value = null;
}

function persistEditResult() {
  replaceVariables(rawData, {
    type: 'script',
    script_id: getScriptId(),
  });
  closeEditModal();
}

function closeEditModal() {
  editOpen.value = false;
  editNodeId.value = null;
  editSnapshot.value = null;
}

function togglePrefixList() {
  showPrefixList.value = !showPrefixList.value;
  if (showPrefixList.value) showSuffixList.value = false;
}

function toggleSuffixList() {
  showSuffixList.value = !showSuffixList.value;
  if (showSuffixList.value) showPrefixList.value = false;
}

/**
 * 设置前缀容器引用
 */
function setPrefixContainerRef(el: any) {
  prefixContainer.value = el;
}

/**
 * 设置后缀容器引用
 */
function setSuffixContainerRef(el: any) {
  suffixContainer.value = el;
}

function getPrefixSuffixKey(item: any): string {
  if (item && typeof item === 'object' && !Array.isArray(item)) {
    const keys = Object.keys(item);
    if (keys.length > 0) return keys[0];
  }
  return '';
}

function getPrefixSuffixValue(item: any): string {
  if (item && typeof item === 'object' && !Array.isArray(item)) {
    const keys = Object.keys(item);
    if (keys.length > 0) {
      const value = item[keys[0]];
      return typeof value === 'string' ? value : String(value);
    }
  }
  return '';
}

/**
 * 点击前缀项时的处理（支持多选）
 *
 * @param item - 被点击的前缀项
 * @param idx - 前缀项索引
 */
function onPrefixItemClick(_item: any, idx: number) {
  if (editMode.value) return;

  if (selectedPrefixIndexes.value.has(idx)) {
    selectedPrefixIndexes.value.delete(idx);
  } else {
    selectedPrefixIndexes.value.add(idx);
  }

  selectedPrefixIndexes.value = new Set(selectedPrefixIndexes.value);
  // 选中项变化会触发 watch，自动调用 applyMacroSubstitution
}

/**
 * 点击后缀项时的处理（支持多选）
 *
 * @param item - 被点击的后缀项
 * @param idx - 后缀项索引
 */
function onSuffixItemClick(_item: any, idx: number) {
  if (editMode.value) return;

  if (selectedSuffixIndexes.value.has(idx)) {
    selectedSuffixIndexes.value.delete(idx);
  } else {
    selectedSuffixIndexes.value.add(idx);
  }

  selectedSuffixIndexes.value = new Set(selectedSuffixIndexes.value);
  // 选中项变化会触发 watch，自动调用 applyMacroSubstitution
}

function openEditPrefixSuffix(
  idx: number,
  type: 'prefix' | 'suffix',
) {
  const list =
    type === 'prefix' ? prefixList.value : suffixList.value;
  const item = list[idx];
  if (!item) return;
  const key = getPrefixSuffixKey(item);
  const value = getPrefixSuffixValue(item);
  editNodeId.value = `${type}:${idx}`;
  editSnapshot.value = {
    title: key,
    name: key,
    canRename: true,
    isLeaf: true,
    value: value,
    children: [],
  };
  editOpen.value = true;
}

/**
 * 打开创建前缀/后缀项的模态框
 *
 * @param type - 创建的类型，'prefix' 或 'suffix'
 */
function openCreatePrefixSuffix(type: 'prefix' | 'suffix') {
  editNodeId.value = `__create__:${type}`;
  editSnapshot.value = {
    title: type === 'prefix' ? '新建前缀' : '新建后缀',
    name: '',
    canRename: true,
    isLeaf: true,
    value: '',
    children: [],
    isCreate: true,
  };
  editOpen.value = true;
}

function sendQuickText() {
  const finalText = text.value;

  triggerSlash(`/send ${finalText}|/trigger`);
  if (onClose) onClose();
}

/**
 * 将酒馆已有文本附加到最后（不应用宏替换）
 */
function appendSillyTavernText() {
  const STText = $('#send_textarea').val();
  if (STText === '' || STText === null) {
    tavernText.value = '';
    applyMacroSubstitution();
    return;
  }
  tavernText.value = String(STText);
  applyMacroSubstitution();
}
</script>

