import { getThemeColors, getParentThemeVariable, removeColorAlpha } from './themeHelper';

/** 降级兜底值（深色模式） */
const DEFAULT_THEME = {
  BlurTintColor: '#1a1a1a',
  ChatTintColor: '#2a2a2a',
  BodyColor: '#e0e0e0',
  QuoteColor: '#4a9eff',
  UnderlineColor: '#6c757d',
  BorderColor: '#3a3a3a',
  ShadowColor: '#000000',
};

/**
 * 将父页面主题 CSS 变量注入到 iframe :root
 * 以 --SmartTheme* 变量名注入，与 index.css 中引用保持一致
 * 仅在 start() 时调用一次，失败时降级为默认主题
 */
export function injectThemeCssVariables(): void {
  const root = document.documentElement;
  try {
    const colors = getThemeColors();
    const shadowColor = removeColorAlpha(getParentThemeVariable('--SmartThemeShadowColor'));
    root.style.setProperty('--SmartThemeBlurTintColor', colors.backgroundColor ?? DEFAULT_THEME.BlurTintColor);
    root.style.setProperty('--SmartThemeChatTintColor', colors.backgroundColorSecondary ?? DEFAULT_THEME.ChatTintColor);
    root.style.setProperty('--SmartThemeBodyColor', colors.textColor ?? DEFAULT_THEME.BodyColor);
    root.style.setProperty('--SmartThemeQuoteColor', colors.primaryColor ?? DEFAULT_THEME.QuoteColor);
    root.style.setProperty('--SmartThemeUnderlineColor', colors.secondaryColor ?? DEFAULT_THEME.UnderlineColor);
    root.style.setProperty('--SmartThemeBorderColor', colors.borderColor ?? DEFAULT_THEME.BorderColor);
    root.style.setProperty('--SmartThemeShadowColor', shadowColor ?? DEFAULT_THEME.ShadowColor);
  } catch (error) {
    console.error('[快捷指令面板] 主题同步失败，使用默认主题', error);
    root.style.setProperty('--SmartThemeBlurTintColor', DEFAULT_THEME.BlurTintColor);
    root.style.setProperty('--SmartThemeChatTintColor', DEFAULT_THEME.ChatTintColor);
    root.style.setProperty('--SmartThemeBodyColor', DEFAULT_THEME.BodyColor);
    root.style.setProperty('--SmartThemeQuoteColor', DEFAULT_THEME.QuoteColor);
    root.style.setProperty('--SmartThemeUnderlineColor', DEFAULT_THEME.UnderlineColor);
    root.style.setProperty('--SmartThemeBorderColor', DEFAULT_THEME.BorderColor);
    root.style.setProperty('--SmartThemeShadowColor', DEFAULT_THEME.ShadowColor);
  }
}
