<template>
  <Dialog
    :visible="modelValue"
    @update:visible="$emit('update:modelValue', $event)"
    :modal="true"
    :draggable="false"
    header="固定前后缀设置"
    :style="{ width: '80dvw', maxWidth: '500px' }"
    :content-style="{ maxHeight: '60dvh', overflow: 'auto' }"
  >
    <!-- 说明信息 -->
    <div
      class="my-1 shrink-0 rounded bg-(--quick-send-bg-sec) p-0.5"
    >
      <div class="kk-text-base opacity-80">
        <span class="icon-[mdi--information-outline]"></span>
        固定前后缀会在发送时自动添加到内容的最前面和最后面（不包括酒馆文本），适用于所有快捷发送内容。
      </div>
    </div>

    <div class="min-h-0 flex-1 overflow-y-auto">
        <!-- 固定前缀输入 -->
        <div class="flex flex-col gap-0.5 mb-0.5">
          <div class="my-0.5 font-semibold">固定前缀</div>
          <Textarea
            v-model="prefixValue"
            class="w-full bg-(--quick-send-bg-sec)! text-(--quick-send-text)!"
            placeholder="输入固定前缀内容..."
            rows="2"
          />
        </div>

        <!-- 固定后缀输入 -->
        <div class="flex flex-col gap-0.5 mb-0.5">
          <div class="my-0.5 font-semibold">固定后缀</div>
          <Textarea
            v-model="suffixValue"
            class="w-full bg-(--quick-send-bg-sec)! text-(--quick-send-text)!"
            placeholder="输入固定后缀内容..."
            rows="2"
          />
        </div>
    </div>

    <template #footer>
      <Button size="small" text label="取消" @click="handleCancel" />
      <Button size="small" label="保存" @click="handleSave" />
    </template>
  </Dialog>
</template>

<script lang="ts" setup>
import { ref, watch } from 'vue';
import Dialog from 'primevue/dialog';
import Button from 'primevue/button';
import Textarea from 'primevue/textarea';

const parentTarget = ref<HTMLElement | null>(null);

const targetElement = window.parent.document.body;

if (targetElement) {
  parentTarget.value = targetElement;
} else {
  console.error(
    'Parent window target element not found: #parent-portal-target',
  );
}

/**
 * 固定前后缀数据结构
 */
export interface FixedPrefixSuffixData {
  /** 固定前缀内容 */
  prefix: string;
  /** 固定后缀内容 */
  suffix: string;
}

const props = defineProps<{
  modelValue: boolean;
  data: FixedPrefixSuffixData | null;
}>();

const emit = defineEmits<{
  'update:modelValue': [value: boolean];
  save: [result: FixedPrefixSuffixData];
}>();

const prefixValue = ref('');
const suffixValue = ref('');

// 监听数据变化，初始化输入框
watch(
  () => props.data,
  d => {
    if (!d) return;
    prefixValue.value = d.prefix ?? '';
    suffixValue.value = d.suffix ?? '';
  },
  { immediate: true },
);

// 监听 modelValue 变化，打开弹窗时绑定 ESC 键
watch(
  () => props.modelValue,
  isOpen => {
    if (isOpen) {
      const handleEsc = (e: KeyboardEvent) => {
        if (e.key === 'Escape') {
          handleCancel();
          document.removeEventListener('keydown', handleEsc);
        }
      };
      document.addEventListener('keydown', handleEsc);
    }
  },
);

function handleSave() {
  const result: FixedPrefixSuffixData = {
    prefix: prefixValue.value,
    suffix: suffixValue.value,
  };
  emit('save', result);
  emit('update:modelValue', false);
}

function handleCancel() {
  emit('update:modelValue', false);
}
</script>
