<template>
  <Dialog
    :visible="modelValue"
    @update:visible="$emit('update:modelValue', $event)"
    :modal="true"
    :draggable="false"
    :header="isCreateMode ? '新建' : '编辑'"
    :style="{ width: '80dvw', maxWidth: '500px' }"
    :content-style="{ maxHeight: '60dvh', overflow: 'auto' }"
  >
    <div class="min-h-0 flex-1 overflow-y-auto">
        <!-- 新建模式下的类型选择（仅在网格层级显示） -->
        <div
          v-if="isCreateMode && createLevel === 'grid'"
          class="flex flex-col gap-0.5 mb-0.5"
        >
          <div class="my-0.5 font-semibold">类型</div>
          <div class="flex flex-wrap gap-0.5">
            <label class="flex cursor-pointer items-center gap-0.5">
              <input
                v-model="createAsLeaf"
                type="radio"
                :value="true"
                name="itemType"
              />
              <span class="whitespace-nowrap">内容</span>
            </label>
            <label class="flex cursor-pointer items-center gap-0.5">
              <input
                v-model="createAsLeaf"
                type="radio"
                :value="false"
                name="itemType"
              />
              <span class="whitespace-nowrap"
                >类别（可添加子项）</span
              >
            </label>
          </div>
        </div>
        <!-- 顶层键名（若允许重命名） -->
        <div
          v-if="snapshot?.canRename || isCreateMode"
          class="flex flex-col gap-0.5 mb-0.5"
        >
          <div class="my-0.5 font-semibold">名称</div>
          <InputText v-model="topName" class="w-full bg-(--quick-send-bg-sec)! text-(--quick-send-text)!" placeholder="输入新的名称" />
        </div>

        <!-- 顶层值（当为叶子字符串时可编辑） -->
        <div
          v-if="snapshot?.isLeaf || (isCreateMode && createAsLeaf)"
          class="flex flex-col gap-0.5"
        >
          <div class="my-0.5 font-semibold">内容</div>
          <Textarea v-model="topValue" class="min-h-5 w-full bg-(--quick-send-bg-sec)! text-(--quick-send-text)!" placeholder="输入内容" />
        </div>
    </div>

    <template #footer>
      <Button size="small" text label="取消" @click="handleCancel" />
      <Button size="small" :label="isCreateMode ? '创建' : '保存'" @click="handleSave" />
    </template>
  </Dialog>
</template>

<script lang="ts" setup>
import { ref, watch } from 'vue';
import Dialog from 'primevue/dialog';
import Button from 'primevue/button';
import InputText from 'primevue/inputtext';
import Textarea from 'primevue/textarea';

/**
 * 仅用于渲染的快照数据结构
 */
export interface EditChildItem {
  /** 统一标识（如 key:xxx / arridx:0） */
  id: string;
  /** 展示与编辑用名称 */
  name: string;
  /** 是否允许重命名 */
  canRename: boolean;
  /** 是否叶子字符串 */
  isLeaf: boolean;
  /** 叶子字符串的值（可编辑） */
  value?: string;
}

export interface EditSnapshot {
  /** 标题（当前正在编辑的键名/项名） */
  title: string;
  /** 顶层是否允许重命名 */
  canRename: boolean;
  /** 顶层是否为叶子 */
  isLeaf: boolean;
  /** 顶层叶子值 */
  value?: string;
  /** 顶层当前名称（用于初始化输入框） */
  name?: string;
  /** 子级列表（仅一层） */
  children: EditChildItem[];
  /** 是否为创建模式 */
  isCreate?: boolean;
  /** 创建时所在的层级 */
  createLevel?: 'l1' | 'l2' | 'grid';
}

const props = defineProps<{
  modelValue: boolean;
  snapshot: EditSnapshot | null;
}>();
const emit = defineEmits<{
  'update:modelValue': [value: boolean];
  save: [
    result: {
      newName?: string;
      newValue?: string;
      children: Array<{
        id: string;
        newName?: string;
        newValue?: string;
      }>;
      __create?: boolean;
      __createAsLeaf?: boolean;
    },
  ];
  delete: [];
}>();

const topName = ref('');
const topValue = ref<string | undefined>(undefined);
const children = ref<EditChildItem[]>([]);

/** 是否为创建模式 */
const isCreateMode = ref(false);
/** 创建时所在的层级 */
const createLevel = ref<'l1' | 'l2' | 'grid'>('grid');
/** 是否创建为叶子节点（字符串） */
const createAsLeaf = ref(true);

watch(
  () => props.snapshot,
  s => {
    if (!s) return;
    isCreateMode.value = s.isCreate ?? false;
    createLevel.value = s.createLevel ?? 'grid';
    // 对于一二级，默认创建数组；对于网格层级，默认创建字符串
    createAsLeaf.value = createLevel.value === 'grid';

    topName.value = s.name ?? s.title ?? '';
    topValue.value = s.isLeaf ? (s.value ?? '') : undefined;
    children.value = (s.children || []).map(c => ({ ...c }));
  },
  { immediate: true },
);

function handleSave() {
  const s = props.snapshot;
  if (!s) return;

  if (isCreateMode.value) {
    // 创建模式
    const result = {
      newName: topName.value,
      newValue: createAsLeaf.value
        ? (topValue.value ?? '')
        : undefined,
      children: [],
      __create: true,
      __createAsLeaf: createAsLeaf.value,
    };
    emit('save', result);
  } else {
    // 编辑模式
    const result = {
      newName: s.canRename ? topName.value : undefined,
      newValue: s.isLeaf ? (topValue.value ?? '') : undefined,
      children: children.value.map(c => ({
        id: c.id,
        newName: c.canRename ? c.name : undefined,
      })),
    };
    emit('save', result);
  }
  emit('update:modelValue', false);
}

function handleCancel() {
  emit('update:modelValue', false);
}
</script>
